#include <bits/stdc++.h>
using namespace std;

int main() {
    char c = 'A';
    cout << int(c) << endl;      // 输出 65
    cout << char(c + 1) << endl; // 输出 B
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    int x = 10;
    int *p = &x;       // p 保存 x 的地址
    *p = 20;           // 修改 p 指向的位置，也就是修改 x
    cout << x << endl; // 输出 20
    return 0;
}
